4	/**
5	 * Rebuilds a typed error from a transport payload.
6	 *
7	 * Electron IPC and the remote-control socket both reduce a rejection to its message text, so
8	 * marker properties such as `code` and `workingFolder` only survive as an explicit payload.
9	 */
10	export function rehydrateBridgeError(payload: BridgeErrorPayload): Error {
11	    if (payload.code === MISSING_WORKING_FOLDER_ERROR && typeof payload.fields.workingFolder === 'string') {
12	        return new MissingWorkingFolderError(payload.fields.workingFolder)
