23	/** Returns the bridge result unchanged, or throws the rehydrated error it carries. */
24	export function unwrapBridgeResult<T>(result: T): T {
25	    const payload = bridgeErrorPayload(result)
26	    if (!payload) return result
27	
28	    throw rehydrateBridgeError(payload)
