41	/** Wraps every method of a bridge so failures resolved as envelopes are thrown as typed errors. */
42	export function withBridgeErrorRehydration<T extends object>(bridge: T): T {
43	    const wrapped: Record<string, unknown> = {}
44	
45	    for (const key of Object.keys(bridge) as (keyof T & string)[]) {
46	        const value = bridge[key]
47	        if (typeof value !== 'function') {
48	            wrapped[key] = value
49	            continue
50	        }
51	
52	        wrapped[key] = (...parameters: unknown[]) => {
53	            const result = (value as (...args: unknown[]) => unknown).apply(bridge, parameters)
54	            if (!isPromiseLike(result)) return unwrapBridgeResult(result)
55	
56	            return unwrapBridgePromise(result)
57	        }
58	    }
59	
60	    return wrapped as T
61	}
